    #[test]
    fn tzdb_2026a_through_2026f_golden_rules() {
        use sad_chrono::Offset;

        // 2026f: America/Havana skips 2026-11-01 fallback, stays -04 through 2027-11-07.
        let havana = Tz::America__Havana;
        for utc_dt in [
            NaiveDate::from_ymd_opt(2026, 11, 1)
                .unwrap()
                .and_hms_opt(3, 59, 59)
                .unwrap(),
            NaiveDate::from_ymd_opt(2026, 11, 1)
                .unwrap()
                .and_hms_opt(4, 0, 0)
                .unwrap(),
            NaiveDate::from_ymd_opt(2026, 11, 1)
                .unwrap()
                .and_hms_opt(5, 0, 0)
                .unwrap(),
        ] {
            let dt = utc_dt.and_utc().with_timezone(&havana);
            assert_eq!(dt.offset().fix().local_minus_utc(), -4 * 3600);
            assert_eq!(dt.offset().to_string(), "CDT");
        }
        let hav_before_2027 = NaiveDate::from_ymd_opt(2027, 11, 7)
            .unwrap()
            .and_hms_opt(4, 59, 59)
            .unwrap()
            .and_utc()
            .with_timezone(&havana);
        assert_eq!(hav_before_2027.offset().fix().local_minus_utc(), -4 * 3600);
        assert_eq!(hav_before_2027.offset().to_string(), "CDT");
        let hav_at_2027 = NaiveDate::from_ymd_opt(2027, 11, 7)
            .unwrap()
            .and_hms_opt(5, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&havana);
        assert_eq!(hav_at_2027.offset().fix().local_minus_utc(), -5 * 3600);
        assert_eq!(hav_at_2027.offset().to_string(), "CST");

        let hav_nov_2026 = NaiveDate::from_ymd_opt(2026, 11, 2)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&havana);
        assert_eq!(hav_nov_2026.offset().fix().local_minus_utc(), -4 * 3600);
        let hav_jan_2027 = NaiveDate::from_ymd_opt(2027, 1, 15)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&havana);
        assert_eq!(hav_jan_2027.offset().fix().local_minus_utc(), -4 * 3600);
        let hav_dec_2027 = NaiveDate::from_ymd_opt(2027, 12, 1)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&havana);
        assert_eq!(hav_dec_2027.offset().fix().local_minus_utc(), -5 * 3600);

        // 2026e: America/Winnipeg moves to permanent -05 (EST) after 2026-10-31.
        let winnipeg = Tz::America__Winnipeg;
        let wpg_jan_2027 = NaiveDate::from_ymd_opt(2027, 1, 15)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&winnipeg);
        assert_eq!(wpg_jan_2027.offset().fix().local_minus_utc(), -5 * 3600);
        assert_eq!(wpg_jan_2027.offset().to_string(), "EST");

        // 2026c: America/Edmonton moves to permanent -06 (CST).
        let edmonton = Tz::America__Edmonton;
        let edm_jan_2027 = NaiveDate::from_ymd_opt(2027, 1, 15)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&edmonton);
        assert_eq!(edm_jan_2027.offset().fix().local_minus_utc(), -6 * 3600);
        assert_eq!(edm_jan_2027.offset().to_string(), "CST");

        // 2026b: America/Vancouver moves to permanent -07 (MST).
        let vancouver = Tz::America__Vancouver;
        let van_jan_2027 = NaiveDate::from_ymd_opt(2027, 1, 15)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&vancouver);
        assert_eq!(van_jan_2027.offset().fix().local_minus_utc(), -7 * 3600);
        assert_eq!(van_jan_2027.offset().to_string(), "MST");

        // 2026d: America/Inuvik moves to permanent -06 (CST).
        let inuvik = Tz::America__Inuvik;
        let inu_jan_2027 = NaiveDate::from_ymd_opt(2027, 1, 15)
            .unwrap()
            .and_hms_opt(12, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&inuvik);
        assert_eq!(inu_jan_2027.offset().fix().local_minus_utc(), -6 * 3600);
        assert_eq!(inu_jan_2027.offset().to_string(), "CST");

        // 2026c: Africa/Casablanca and Africa/El_Aaiun move to permanent +00 after 2026-09-20 02:00.
        for morocco in [Tz::Africa__Casablanca, Tz::Africa__El_Aaiun] {
            let before = NaiveDate::from_ymd_opt(2026, 9, 19)
                .unwrap()
                .and_hms_opt(12, 0, 0)
                .unwrap()
                .and_utc()
                .with_timezone(&morocco);
            assert_eq!(before.offset().fix().local_minus_utc(), 3600);

            let after = NaiveDate::from_ymd_opt(2026, 9, 21)
                .unwrap()
                .and_hms_opt(12, 0, 0)
                .unwrap()
                .and_utc()
                .with_timezone(&morocco);
            assert_eq!(after.offset().fix().local_minus_utc(), 0);

            let summer_2027 = NaiveDate::from_ymd_opt(2027, 7, 1)
                .unwrap()
                .and_hms_opt(12, 0, 0)
                .unwrap()
                .and_utc()
                .with_timezone(&morocco);
            assert_eq!(summer_2027.offset().fix().local_minus_utc(), 0);
        }

        // 2026a: Europe/Chisinau aligned with EU transition times (01:00 UTC).
        let chisinau = Tz::Europe__Chisinau;
        let md_before = NaiveDate::from_ymd_opt(2026, 3, 29)
            .unwrap()
            .and_hms_opt(0, 59, 59)
            .unwrap()
            .and_utc()
            .with_timezone(&chisinau);
        assert_eq!(md_before.offset().fix().local_minus_utc(), 2 * 3600);
        let md_after = NaiveDate::from_ymd_opt(2026, 3, 29)
            .unwrap()
            .and_hms_opt(1, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&chisinau);
        assert_eq!(md_after.offset().fix().local_minus_utc(), 3 * 3600);

        // 2026d: POSIX USback zones follow US DST rules.
        for (tz, std_hours) in [
            (Tz::EST5EDT, -5),
            (Tz::CST6CDT, -6),
            (Tz::MST7MDT, -7),
            (Tz::PST8PDT, -8),
        ] {
            let winter = NaiveDate::from_ymd_opt(2026, 12, 1)
                .unwrap()
                .and_hms_opt(12, 0, 0)
                .unwrap()
                .and_utc()
                .with_timezone(&tz);
            assert_eq!(winter.offset().fix().local_minus_utc(), std_hours * 3600);

            let summer = NaiveDate::from_ymd_opt(2026, 7, 1)
                .unwrap()
                .and_hms_opt(12, 0, 0)
                .unwrap()
                .and_utc()
                .with_timezone(&tz);
            assert_eq!(
                summer.offset().fix().local_minus_utc(),
                (std_hours + 1) * 3600
            );
        }
    }

    #[test]
    fn brazil_1965_1966_transition_edges() {
        use sad_chrono::Offset;

        let sp = Tz::America__Sao_Paulo;
        // Decree 55,639: 1965-01-31 00:00 (-03) -> 03:00:00 UTC starts -02 DST
        let before_jan65 = NaiveDate::from_ymd_opt(1965, 1, 31)
            .unwrap()
            .and_hms_opt(2, 59, 59)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(before_jan65.offset().fix().local_minus_utc(), -3 * 3600);
        let at_jan65 = NaiveDate::from_ymd_opt(1965, 1, 31)
            .unwrap()
            .and_hms_opt(3, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(at_jan65.offset().fix().local_minus_utc(), -2 * 3600);

        // Decree 55,639: 1965-03-31 24:00 (-02) -> 1965-04-01 02:00:00 UTC returns to -03
        let before_apr65 = NaiveDate::from_ymd_opt(1965, 4, 1)
            .unwrap()
            .and_hms_opt(1, 59, 59)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(before_apr65.offset().fix().local_minus_utc(), -2 * 3600);
        let at_apr65 = NaiveDate::from_ymd_opt(1965, 4, 1)
            .unwrap()
            .and_hms_opt(2, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(at_apr65.offset().fix().local_minus_utc(), -3 * 3600);

        // Decree 57,303: 1965-11-30 24:00 (-03) -> 1965-12-01 03:00:00 UTC starts -02 DST
        let before_dec65 = NaiveDate::from_ymd_opt(1965, 12, 1)
            .unwrap()
            .and_hms_opt(2, 59, 59)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(before_dec65.offset().fix().local_minus_utc(), -3 * 3600);
        let at_dec65 = NaiveDate::from_ymd_opt(1965, 12, 1)
            .unwrap()
            .and_hms_opt(3, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(at_dec65.offset().fix().local_minus_utc(), -2 * 3600);

        // Decree 57,843: 1966-03-01 01:00 wall (-02) -> 03:00:00 UTC returns to -03
        let before_mar66 = NaiveDate::from_ymd_opt(1966, 3, 1)
            .unwrap()
            .and_hms_opt(2, 59, 59)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(before_mar66.offset().fix().local_minus_utc(), -2 * 3600);
        let at_mar66 = NaiveDate::from_ymd_opt(1966, 3, 1)
            .unwrap()
            .and_hms_opt(3, 0, 0)
            .unwrap()
            .and_utc()
            .with_timezone(&sp);
        assert_eq!(at_mar66.offset().fix().local_minus_utc(), -3 * 3600);
    }

    #[test]
    fn test_type_size() {
        use super::TzOffset;
        use sad_chrono::DateTime;

        assert!(core::mem::size_of::<TzOffset>() <= 8);
        assert!(core::mem::size_of::<DateTime<Tz>>() <= 24);
        #[cfg(not(feature = "filter-by-regex"))]
        {
            assert_eq!(core::mem::size_of::<TzOffset>(), 4);
            assert_eq!(core::mem::size_of::<DateTime<Tz>>(), 16);
        }
    }

    #[test]
    fn tz_offset_partial_eq_preserves_0110_semantics() {
        use super::America::{New_York, Toronto};

        let ny_jan_2024 = New_York.with_ymd_and_hms(2024, 1, 15, 12, 0, 0).unwrap();
        let ny_jan_2025 = New_York.with_ymd_and_hms(2025, 1, 15, 12, 0, 0).unwrap();
        let ny_jul_2024 = New_York.with_ymd_and_hms(2024, 7, 15, 12, 0, 0).unwrap();
        let tor_jan_2024 = Toronto.with_ymd_and_hms(2024, 1, 15, 12, 0, 0).unwrap();

        assert_eq!(ny_jan_2024.offset(), ny_jan_2025.offset());
        assert_ne!(ny_jan_2024.offset(), ny_jul_2024.offset());
        assert_ne!(ny_jan_2024.offset(), tor_jan_2024.offset());
    }

    #[test]
    fn tz_variants_discriminants_match_indices() {
        for (idx, &tz) in super::TZ_VARIANTS.iter().enumerate() {
            assert_eq!(tz as usize, idx);
        }
    }
